  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tasks_phase`(`phase_id` ASC) USING BTREE,
  INDEX `idx_tasks_user`(`user_id` ASC) USING BTREE,
  INDEX `idx_tasks_status`(`status` ASC) USING BTREE,
  CONSTRAINT `fk_tasks_phase` FOREIGN KEY (`phase_id`) REFERENCES `path_phases` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_tasks_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
