  `current_industry` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前行业',
  `target_position` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '目标职位',
  `target_time_years` int NULL DEFAULT 3 COMMENT '目标达成时间(年)',
  `weekly_hours` int NULL DEFAULT 10 COMMENT '每周可投入学习时间(小时)',
  `interests` json NULL COMMENT '兴趣标签列表',
  `values_pref` json NULL COMMENT '职业价值观偏好',
  `learning_style` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT 'mixed' COMMENT '学习风格: visual/reading/practice/mixed',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_profiles_user`(`user_id` ASC) USING BTREE,
  CONSTRAINT `fk_profiles_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 101 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户资料表' ROW_FORMAT = Dynamic;

